import { createHash as createHash2 } from "crypto";
import { stat as stat3 } from "fs/promises";
import { join as join7, resolve as resolve2 } from "path";
function emptyResult() {
  return {
    skillRoots: [],
    diagnostics: [],
    fingerprints: []
  };
}
function isExternalSource(value) {
  const normalized = value.trim().toLowerCase();
  if (!normalized) {
    return true;
  }
  if (normalized.startsWith("http://") || normalized.startsWith("https://") || normalized.startsWith("git@") || normalized.includes("://")) {
    return true;
  }
  if (normalized === "github" || normalized === "git" || normalized === "url") {
    return true;
  }
  return false;
}
function normalizeLocalPluginSource(source) {
  if (typeof source === "string") {
    if (isExternalSource(source)) {
      return null;
    }
    return source.trim().replace(/^[.][\\/]/, "");
  }
  if (!source || typeof source !== "object" || Array.isArray(source)) {
    return null;
  }
  const record = source;
  if (typeof record.path === "string" && !isExternalSource(record.path)) {
    return record.path.trim().replace(/^[.][\\/]/, "");
  }
  if (typeof record.source === "string" && !isExternalSource(record.source)) {
    return record.source.trim().replace(/^[.][\\/]/, "");
  }
  return null;
}
async function isDirectory(path) {
  try {
    return (await stat3(path)).isDirectory();
  } catch {
    return false;
  }
}
async function discoverMarketplaceSkillRoots(args) {
  const manifestPath = join7(args.rootPath, ".claude-plugin", "marketplace.json");
  const manifestText = await readTextIfExists(manifestPath);
  if (!manifestText) {
    return emptyResult();
  }
  const diagnostics = [];
  const fingerprints = [
    `marketplace:${manifestPath}:${createHash2("sha1").update(manifestText).digest("hex")}`
  ];
  let manifest;
  try {
    manifest = JSON.parse(manifestText);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    diagnostics.push({
      type: "warning",
      message: `Failed to parse marketplace.json (${args.source}): ${message}`,
      path: manifestPath
    });
    return {
      skillRoots: [],
      diagnostics,
      fingerprints
    };
  }
  if (!manifest || typeof manifest !== "object" || Array.isArray(manifest)) {
    diagnostics.push({
      type: "warning",
      message: "Invalid marketplace manifest; expected JSON object.",
      path: manifestPath
    });
    return {
      skillRoots: [],
      diagnostics,
      fingerprints
    };
  }
  if (!Array.isArray(manifest.plugins)) {
    diagnostics.push({
      type: "warning",
      message: "Invalid marketplace manifest; missing plugins array.",
      path: manifestPath
    });
    return {
      skillRoots: [],
      diagnostics,
      fingerprints
    };
  }
  const roots = [];
  for (let index = 0;index < manifest.plugins.length; index += 1) {
    const entry = manifest.plugins[index];
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
      diagnostics.push({
        type: "warning",
        message: `Invalid marketplace plugin entry at index ${index}.`,
        path: manifestPath
      });
      continue;
    }
    const plugin = entry;
    const pluginName = typeof plugin.name === "string" && plugin.name.trim() ? plugin.name.trim() : `plugin-${index + 1}`;
    const localSource = normalizeLocalPluginSource(plugin.source);
    if (!localSource) {
      continue;
    }
    const pluginRoot = resolve2(args.rootPath, localSource);
    if (!await isDirectory(pluginRoot)) {
      diagnostics.push({
        type: "warning",
        message: `Marketplace plugin "${pluginName}" source path not found: ${localSource}`,
        path: manifestPath
      });
      continue;
    }
    const skillsRoot = join7(pluginRoot, "skills");
    if (!await isDirectory(skillsRoot)) {
      continue;
    }
    roots.push(skillsRoot);
    fingerprints.push(`marketplace-plugin:${pluginName}:${skillsRoot}`);
  }
  return {
    skillRoots: [...new Set(roots)].sort((left, right) => left.localeCompare(right)),
    diagnostics,
    fingerprints
  };
}

