    "api",
    "graphql",
    "-f",
    `query=${mutation}`,
    "-f",
    `repositoryId=${repositoryId}`,
    "-f",
    `categoryId=${categoryId}`,
    "-f",
    `title=${buildIssueTitle(input.message?.trim() ?? "")}`,
    "-f",
    `body=${truncateDiscussionBody(buildIssueBody(input))}`
