      const laneSpecs = [
        {
          threadId: this.agent.workerThreadId,
          laneRole: "primary",
          laneIndex: 1
        },
        ...helperThreadIds.map((threadId, index) => ({
          threadId,
          laneRole: "helper",
          laneIndex: index + 2
        }))
      ];
      const activeLaneCount = laneSpecs.length;
      const settledRuns = await Promise.allSettled(laneSpecs.map(async (lane) => await this.runWorkerLane({
        threadId: lane.threadId,
        input: this.withParallelLaneInput(input, lane.laneIndex, lane.laneRole, activeLaneCount),
        laneRole: lane.laneRole,
        laneIndex: lane.laneIndex
      })));
      const completedLanes = [];
      const helperErrors = [];
      let primaryError = null;
      for (let index = 0;index < settledRuns.length; index += 1) {
        const runResult = settledRuns[index];
        const laneSpec = laneSpecs[index];
        if (runResult?.status === "fulfilled") {
          completedLanes.push(runResult.value);
          continue;
        }
        const laneLabel = `lane-${laneSpec?.laneIndex ?? index + 1}`;
        const reason = runResult?.reason instanceof Error ? runResult.reason.message : String(runResult?.reason ?? "unknown worker lane failure");
        if (laneSpec?.laneRole === "primary") {
          primaryError = reason;
        } else {
          helperErrors.push(`${laneLabel}: ${reason}`);
        }
      }
      if (primaryError) {
        throw new Error(primaryError);
      }
      const primaryLane = completedLanes.find((lane) => lane.laneRole === "primary");
      if (!primaryLane) {
        throw new Error("Primary worker lane did not return a result");
      }
      const helperLanes = completedLanes.filter((lane) => lane.laneRole === "helper");
      let artifacts = this.mergeWorkerLaneResults(primaryLane, helperLanes, helperErrors);
      artifacts = {
        ...artifacts,
        plan: normalizePlanSteps(artifacts.plan)
      };
      const completionGate = enforcePlanCompletionGate({
        output: artifacts.parsed,
        plan: artifacts.plan
      });
      if (completionGate.gated) {
        const gateMessage = completionGate.reason === "missing_plan" ? "Completion claim gated because worker emitted no plan updates." : "Completion claim gated because plan still has incomplete steps.";
        artifacts = {
          ...artifacts,
          parsed: completionGate.output,
          finalMessage: JSON.stringify(completionGate.output)
        };
        await this.record("system", "plan-gate", {
          message: gateMessage,
          reason: completionGate.reason,
          unresolvedSteps: completionGate.unresolvedSteps
        });
      }
